void kppImGui_LogText(const char* fmt, ...)
{
  va_list args;
  va_start(args, fmt);
  int length = vsnprintf(nullptr, 0, fmt, args);
  va_end(args);
  char* text = (char*)malloc((size_t)length + 1);
  va_start(args, fmt);
  vsnprintf(text, (size_t)length + 1, fmt, args);
  va_end(args);
  ImGui::LogText("%s", text);
  free(text);
}
